//! `java.util.Currency`: the ISO 4217 codes the JDK knows, each region's currency, and `getSymbol(locale)`, all
//! recorded from the JDKs (`super::currency_data`, generated by `reference/gen_currency.py`).

use super::currency_data::{CODES, JAVABASE, JDK21, JDK26, REGIONS, SYMBOL_SETS};
use crate::text::{Locale, LocaleData};

/// A `java.util.Currency`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Currency {
    code: &'static str,
    fraction_digits: i8,
    numeric: u16,
}

impl Currency {
    /// `Currency.getInstance(String)`: `None` where the JDK throws `IllegalArgumentException` (anything but one of
    /// its upper-case three-letter codes).
    pub fn get_instance(code: &str) -> Option<Currency> {
        let i = CODES.binary_search_by(|e| e.0.cmp(code)).ok()?;
        let (code, fraction_digits, numeric) = CODES[i];
        Some(Currency { code, fraction_digits, numeric })
    }

    /// `Currency.getInstance(Locale)` of the locale's country: `Err(())` where the JDK throws
    /// `IllegalArgumentException` (an empty or unknown region), `Ok(None)` for a region without a currency (`AQ`).
    #[allow(clippy::result_unit_err)]
    pub fn for_country(country: &str) -> Result<Option<Currency>, ()> {
        let i = REGIONS.binary_search_by(|e| e.0.cmp(country)).map_err(|_| ())?;
        Ok(Currency::get_instance(REGIONS[i].1))
    }

    /// `getCurrencyCode()`.
    pub fn currency_code(&self) -> &'static str {
        self.code
    }

    /// `getDefaultFractionDigits()`: -1 for pseudo-currencies (`XXX`, `XAU`, ...).
    pub fn default_fraction_digits(&self) -> i32 {
        self.fraction_digits as i32
    }

    /// `getNumericCode()`.
    pub fn numeric_code(&self) -> i32 {
        self.numeric as i32
    }

    /// `getSymbol(locale)`: the locale's own recorded symbols, else its language's, else those of a language the JDK
    /// has no data for; the code itself where the locale data has no symbol.
    pub fn symbol(&self, locale: &Locale) -> &'static str {
        let set = SYMBOL_SETS[symbol_set(locale) as usize];
        match set.binary_search_by(|e| e.0.cmp(self.code)) {
            Ok(i) => set[i].1,
            Err(_) => self.code,
        }
    }
}

/// The recorded symbol set `locale` resolves to in its JDK's table.
fn symbol_set(locale: &Locale) -> u16 {
    let table: &[(&str, u16)] = match locale.locale_data() {
        LocaleData::Full => &JDK26,
        LocaleData::FullJdk21 => &JDK21,
        LocaleData::JavaBase => &JAVABASE,
    };
    let find = |tag: &str| table.binary_search_by(|e| e.0.cmp(tag)).ok().map(|i| table[i].1);
    let (language, country) = (locale.language(), locale.country());
    (!country.is_empty())
        .then(|| find(&format!("{language}_{country}")))
        .flatten()
        .or_else(|| find(language))
        .or_else(|| find("xx"))
        .expect("every table records xx")
}
